private fun day()=SimpleDateFormat("yyyy-MM-dd",Locale.US).format(Date())
private fun time()=SimpleDateFormat("dd MMM yyyy, HH:mm",Locale("id","ID")).format(Date())
private fun arr(p:android.content.SharedPreferences,k:String)=JSONArray(p.getString(k,"[]")?:"[]")
private fun save(p:android.content.SharedPreferences,k:String,a:JSONArray){p.edit().putString(k,a.toString()).apply()}
private fun activity(p:android.content.SharedPreferences,name:String,points:Int){val a=arr(p,"activities");a.put(JSONObject().put("day",day()).put("time",time()).put("name",name).put("points",points));save(p,"activities",a);val old=p.getString("active_day","")?:"";val water=p.getInt("water",0);p.edit().putInt("water",(water-points*5).coerceAtLeast(0)).putString("active_day",day()).putString("water_day",day()).putInt("inactive",0).apply()}
private fun water(p:android.content.SharedPreferences):Int{val last=p.getString("water_day","")?:"";val current=p.getInt("water",0);if(last.isBlank()){p.edit().putString("water_day",day()).apply();return current};val gap=try{(java.time.LocalDate.parse(day()).toEpochDay()-java.time.LocalDate.parse(last).toEpochDay()).toInt().coerceAtLeast(0)}catch(_:Exception){0};if(gap>0){val inactive=p.getInt("inactive",0)+gap;val rise=if(inactive<=2)0 else (inactive-2)*10;p.edit().putInt("water",(current+rise).coerceAtMost(100)).putInt("inactive",inactive).putString("water_day",day()).apply()};return p.getInt("water",0)}
@Composable private fun FulkApp(){val c=LocalContext.current;val p= remember{c.getSharedPreferences("fulk",Context.MODE_PRIVATE)};var page by remember{mutableStateOf("Beranda")};var chosen by remember{mutableStateOf<F?>(null)};var verse by remember{mutableStateOf(false)};var theme by remember{mutableStateOf(p.getString("theme","system")?:"system")};val system=androidx.compose.foundation.isSystemInDarkTheme();val dark=theme=="dark"||(theme=="system"&&system);MaterialTheme(colorScheme=if(dark)darkColorScheme(primary=Color(0xFF8ABEFF),secondary=Color(0xFF70C8C0)) else lightColorScheme(primary=Blue,secondary=Teal,background=Warm,surface=Color.White,onSurface=Navy)){Scaffold(containerColor=MaterialTheme.colorScheme.background,bottomBar={NavigationBar{listOf("Beranda","Aktivitas","Jurnal","Profil").forEach{val ic=when(it){"Beranda"->Icons.Outlined.Home;"Aktivitas"->Icons.Outlined.CheckCircle;"Jurnal"->Icons.Outlined.EditNote;else->Icons.Outlined.Person};NavigationBarItem(selected=page==it&&chosen==null,onClick={page=it;chosen=null;verse=false},icon={Icon(ic,null)},label={Text(it)})}}}){pad->if(chosen!=null&&!verse)Verse(chosen!!,Modifier.padding(pad),{verse=true},{chosen=null})else if(chosen!=null)Feature(chosen!!,Modifier.padding(pad),p,{chosen=null;verse=false})else when(page){"Beranda"->Home(Modifier.padding(pad),p){chosen=it;verse=false};"Aktivitas"->ListPage(Modifier.padding(pad),"Aktivitas",arr(p,"activities"),"name");"Jurnal"->ListPage(Modifier.padding(pad),"Jurnal",arr(p,"journals"),"text");else->Profile(Modifier.padding(pad),theme){theme=it;p.edit().putString("theme",it).apply()}}}}}
@Composable private fun Page(m:Modifier=Modifier,body:@Composable ColumnScope.()->Unit){Column(m.fillMaxSize().verticalScroll(rememberScrollState()).padding(18.dp),content=body)}
@Composable private fun Home(m:Modifier,p:android.content.SharedPreferences,open:(F)->Unit){Page(m){Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(46.dp).clip(RoundedCornerShape(14.dp)).background(Blue),contentAlignment=Alignment.Center){Icon(Icons.Outlined.Shield,null,tint=Color.White)};Spacer(Modifier.width(10.dp));Column{Text("FULK",fontSize=25.sp,fontWeight=FontWeight.ExtraBold);Text("Kelola informasi dengan sadar",fontSize=12.sp,color=Muted)}};Spacer(Modifier.height(18.dp));Column(Modifier.fillMaxWidth().clip(RoundedCornerShape(24.dp)).background(Brush.linearGradient(listOf(Blue,Navy))).padding(20.dp)){Text("Halo, selamat datang!",fontSize=23.sp,fontWeight=FontWeight.Bold,color=Color.White);Text("Jaga waktu, periksa informasi, dan bangun kebiasaan digital yang lebih sehat.",color=Color.White);Spacer(Modifier.height(14.dp));Text("Aktivitas hari ini: ${(0 until arr(p,"activities").length()).count{arr(p,"activities").optJSONObject(it)?.optString("day")==day()}}",color=Color.White);Text("Air Reflect: ${water(p)}%",color=Color.White)};Spacer(Modifier.height(20.dp));Text("Fitur utama",fontSize=20.sp,fontWeight=FontWeight.Bold);fs.chunked(2).forEach{r->Row(horizontalArrangement=Arrangement.spacedBy(12.dp)){r.forEach{f->Column(Modifier.weight(1f).padding(vertical=6.dp).clip(RoundedCornerShape(18.dp)).background(MaterialTheme.colorScheme.surface).clickable{open(f)}.padding(14.dp).heightIn(min=125.dp)){Box(Modifier.size(40.dp).clip(RoundedCornerShape(12.dp)).background(Sky),contentAlignment=Alignment.Center){Icon(f.icon,null,tint=Blue)};Spacer(Modifier.height(10.dp));Text(f.name,fontWeight=FontWeight.Bold);Text(f.desc,fontSize=12.sp,color=Muted)}};if(r.size==1)Spacer(Modifier.weight(1f))}}}}
