@Composable private fun Time(p:android.content.SharedPreferences){var limit by remember{mutableIntStateOf(p.getInt("limit",120))};var remind by remember{mutableIntStateOf(p.getInt("remind",10))};var group by remember{mutableStateOf(p.getString("group","Media sosial")?:"Media sosial")};Text("Batas waktu harian: $limit menit",fontWeight=FontWeight.Bold);Slider(value=limit.toFloat(),onValueChange={limit=it.toInt()},valueRange=30f..360f,steps=10);Text("Pengingat sebelum batas");Row{listOf(5,10,15,20).forEach{FilterChip(remind==it,{remind=it},label={Text("$it m")})}};OutlinedTextField(group,{group=it},label={Text("Kelompok aplikasi")},modifier=Modifier.fillMaxWidth());Button(onClick={p.edit().putInt("limit",limit).putInt("remind",remind).putString("group",group).apply()},modifier=Modifier.fillMaxWidth()){Text("Simpan batas")};var info by remember{mutableStateOf(false)};OutlinedButton(onClick={info=true},modifier=Modifier.fillMaxWidth()){Text("Konfigurasi izin Smart Pause")};if(info){val context=LocalContext.current;AlertDialog(onDismissRequest={info=false},title={Text("Izin Android")},text={Text("Untuk Usage Access, buka pengaturan akses penggunaan. Overlay memerlukan izin tampil di atas aplikasi lain. Service pemantauan dan pop-up lintas aplikasi belum diaktifkan pada versi ini.")},confirmButton={TextButton(onClick={try{context.startActivity(Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS))}catch(_:Exception){};info=false}){Text("Buka Usage Access")}},dismissButton={TextButton(onClick={info=false}){Text("Tutup")}})};Text("Pengaturan tersimpan secara lokal. Pengingat lintas aplikasi otomatis belum aktif.",color=Muted,fontSize=12.sp)}
private fun score(s:String):Pair<String,String>{val keys=listOf("bit.ly","tinyurl","bonus","hadiah","menang","slot","judi","otp","transfer sekarang","klaim hadiah","gratis");val found=keys.filter{s.lowercase().contains(it)};return when{found.size>=2->"Perlu diwaspadai" to "Pola ditemukan: ${found.joinToString()}. Pemeriksaan heuristik, bukan pemindaian keamanan penuh.";found.size==1->"Perlu diperiksa" to "Indikator: ${found[0]}. Verifikasi domain dan pengirim.";else->"Tidak ada pola sederhana terdeteksi" to "Ini bukan jaminan aman. Jangan masukkan OTP, PIN, kata sandi, atau data bank melalui tautan tidak dipercaya."}}
@Composable private fun Shield(){var text by remember{mutableStateOf("")};var result by remember{mutableStateOf<Pair<String,String>?>(null)};Text("Tempel URL atau pesan mencurigakan.");OutlinedTextField(text,{text=it},modifier=Modifier.fillMaxWidth(),minLines=3);Button(onClick={result=if(text.isBlank())"Belum ada input" to "Tempel teks terlebih dahulu." else score(text)},modifier=Modifier.fillMaxWidth()){Text("Periksa indikator")};result?.let{Card{Column(Modifier.padding(14.dp)){Text(it.first,fontWeight=FontWeight.Bold);Text(it.second)}}};Text("Belum memblokir situs otomatis dan tidak memindai seluruh aplikasi. Hasil heuristik tidak menjamin keamanan.",fontSize=12.sp,color=Muted)}
