@Composable private fun Reflect(p:android.content.SharedPreferences){var note by remember{mutableStateOf("")};val w=water(p);Card(colors=CardDefaults.cardColors(containerColor=Sky)){Column(Modifier.padding(16.dp)){Text("Air refleksi",color=Navy,fontWeight=FontWeight.Bold);Text("$w%",fontSize=34.sp,fontWeight=FontWeight.ExtraBold,color=Blue);LinearProgressIndicator(progress={w/100f},modifier=Modifier.fillMaxWidth());Text("Metafora muhasabah, bukan ukuran klinis.",color=Navy,fontSize=12.sp)}};Spacer(Modifier.height(12.dp));val tasks=listOf("Selesaikan modul Learn" to 3,"Selesaikan pemeriksaan Check" to 3,"Kelola paparan digital" to 2,"Tulis refleksi" to 2,"Laporkan pengurangan waktu media sosial" to 1);tasks.forEach{(s,n)->Button(onClick={activity(p,s,n)},modifier=Modifier.fillMaxWidth().padding(vertical=3.dp)){Text("$s (−${n*5} poin air)")}};OutlinedTextField(note,{note=it},modifier=Modifier.fillMaxWidth(),label={Text("Catatan refleksi")},minLines=3);Button(onClick={if(note.isNotBlank()){val a=arr(p,"journals");a.put(JSONObject().put("time",time()).put("text",note));save(p,"journals",a);activity(p,"Menulis refleksi",2);note=""}},modifier=Modifier.fillMaxWidth()){Text("Simpan jurnal")};Text("Aturan: +10% per hari setelah dua hari masa tenggang; setiap poin aktivitas −5%. Data air lokal; pengingat harian otomatis belum aktif.",fontSize=12.sp,color=Muted)}
